def solve(inputs: dict) -> float:
    import re
    def find(keys):
        for k in keys:
            if k in inputs:
                return inputs[k]
        return None
    base = find(['base', 'b', 'a', 'x'])
    exp = find(['exp', 'exponent', 'e', 'power', 'p', 'n'])
    mod = find(['mod', 'm', 'modulus'])
    if None in (base, exp, mod):
        text = None
        for v in inputs.values():
            if isinstance(v, str):
                text = v
                break
        if text is not None:
            nums = [int(x) for x in re.findall(r'-?\d+', text)]
            base, exp, mod = nums[0], nums[1], nums[2]
    return float(pow(int(base), int(exp), int(mod)))

